  },
  passwordInput: function (e) {
    this.data.password = e.detail.value
  },
  qqnumInput: function (e) {
    this.data.qqnum = e.detail.value
  },
  officenumInput: function (e) {
    this.data.officenum = e.detail.value
  },
  regist: function (e) {
    if (this.data.username == '') {
      wx.showModal({
        title: "提示！",
        content: "请输入姓名",
        showCancel: false,
        success: res => ({

        })
      })
    } else if (this.data.password == '') {
      wx.showModal({
        title: "提示！",
        content: "请输入学号",
        showCancel: false,
        success: res => ({

        }),
      })
    } else if (this.data.password < 201820101) {
      wx.showModal({
        title: "提示！",
        content: "学号不符合要求",
        showCancel: false,
        success: res => ({

        }),
      })
    }
    /*
    else if (this.data.officenum == '') {
      wx.showModal({
        title: "提示！",
        content: "请输入安排的职务",
        showCancel: false,
        success: res => ({

        })
      })
    } 
    */
    else {
      this.data.password = this.data.password * 1
      userInfo.where({
        _id: this.data.password,
        name: this.data.username
      }).get().then(res => {
        // console.log(res.data)
        if (res.data.length === 0) {
